        if ie is not None and ea is not None and ie - ea > 1e-6:
            chi[i] = 0.5 * (ie + ea)
            hardness[i] = ie - ea
    near = [1e30 for a in sites]
    neighbors = s.get('neighbors') or []
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            near[i] = min(near[i], d)
    total = 0.0
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 1e-8 < d <= 1.3 * near[i]:
            if chi[i] is not None and chi[j] is not None:
                scale = (chi[i] - chi[j]) ** 2 / (2.0 * (hardness[i] + hardness[j]))
                total += occ[i] * occ[j] * exp(-2.0 * (d / near[i] - 1.0)) * scale
    return total / (2.0 * weight)

