        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    radii = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    near = [1e30 for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                near[i] = min(near[i], d / (ri + rj))
    total = 0.0
    weight = 0.0
    for i in range(n):
        if near[i] < 1e30:
            total += occ[i] * max(near[i] - 1.0, 0.0) ** 2
            weight += occ[i]
    return total / weight if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    elements = [a.get('element') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    abundance = {}
    weight = 0.0
    for i in range(n):
        if elements[i] is not None:
            abundance[elements[i]] = abundance.get(elements[i], 0.0) + occ[i]
            weight += occ[i]
    if weight <= 0:
        return 0.0
    expected = 1.0 - sum((x / weight) ** 2 for x in abundance.values())
    near = [1e30 for a in sites]
    neighbors = s.get('neighbors') or []
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            near[i] = min(near[i], d)
    hetero = 0.0
    contacts = 0.0
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 1e-8 < d <= 1.3 * near[i]:
            if elements[i] is not None and elements[j] is not None:
                w = occ[i] * occ[j]
                contacts += w
                if elements[i] != elements[j]:
                    hetero += w
    return hetero / contacts - expected if contacts > 0 else 0.0

